const cn = (...classes) => classes.filter(Boolean).join(' ');

function Shell({ children }) {
  const [location] = useLocation();
  const [open, setOpen] = useState(false);
  const [online, setOnline] = useState(connectivityService.isOnline());
  useEffect(() => connectivityService.subscribe(() => setOnline(connectivityService.isOnline())), []);
  useEffect(() => setOpen(false), [location]);
  return (
    <div className="noise min-h-[100dvh] bg-[#edf7f6]">
      <header className="fixed inset-x-0 top-0 z-40 h-14 border-b border-[#cfe4e2] bg-[#f8fcfb]/95 backdrop-blur-xl">
        <div className="flex h-full items-center justify-between px-4 sm:px-6 lg:pl-[252px]">
          <div className="flex items-center gap-3">
            <button onClick={() => setOpen(true)} className="rounded-lg p-2 text-[#195b63] hover:bg-[#e2f0ee] lg:hidden" aria-label="Open navigation" data-testid="button-open-navigation"><Menu size={19} /></button>
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-[9px] bg-[#0e636d] text-white shadow-sm"><Waves size={16} /></div>
              <span className="text-[13px] font-bold tracking-[.18em] text-[#144b53]">ORCA</span>
              <span className="hidden text-[10px] font-medium uppercase tracking-[.16em] text-[#729194] sm:block">Marine intelligence</span>
            </div>
          </div>
          <div className="flex items-center gap-2.5 text-[11px]">
            <div className="hidden items-center gap-1.5 rounded-full border border-[#d2e7e4] bg-white px-3 py-1.5 text-[#567276] sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-[#e79136]" /> DEMO DATA <span className="text-[#a3b8b6]">·</span> 06:42 IST</div>
            <div className={cn('flex items-center gap-1.5 rounded-full border px-3 py-1.5 font-medium', online ? 'border-[#cbe7d8] bg-[#f3fbf6] text-[#28734e]' : 'border-[#f0d5bd] bg-[#fff8f0] text-[#a15a28]')} data-testid="status-connectivity">
              {online ? <Wifi size={13} /> : <WifiOff size={13} />} {online ? 'Online' : 'Offline'}
            </div>
            <button className="hidden rounded-lg p-2 text-[#55777a] hover:bg-[#e2f0ee] sm:block" aria-label="Settings" data-testid="button-settings"><Settings2 size={17} /></button>
            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d8ebe8] text-[11px] font-bold text-[#16606a]" data-testid="avatar-operator">AK</div>
          </div>
        </div>
      </header>
      <aside className={cn('fixed bottom-0 left-0 top-0 z-50 w-[236px] border-r border-[#244951] bg-[#12353d] px-3 py-5 text-[#d7ece9] transition-transform duration-300 lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full lg:block')}>
        <div className="mb-9 flex items-center justify-between px-3">
          <div><div className="text-[11px] font-bold uppercase tracking-[.2em] text-[#f2b45f]">ORCA / 26</div><div className="mt-1 text-[11px] text-[#8eb5b3]">Marine decision support</div></div>
          <button onClick={() => setOpen(false)} className="rounded-lg p-1 text-[#87afad] hover:bg-[#1b4b54] lg:hidden" aria-label="Close navigation" data-testid="button-close-navigation"><X size={18} /></button>
        </div>
        <nav className="space-y-6">
          {navGroups.map((group) => <div key={group.label}><div className="mb-2 px-3 text-[9px] font-bold uppercase tracking-[.18em] text-[#709c9d]">{group.label}</div><div className="space-y-1">{group.items.map((item) => {
            const Icon = item.icon;
            const active = location === item.href;
            return <Link key={item.href} href={item.href} className={cn('group flex items-center justify-between rounded-xl px-3 py-2.5 text-[12px] font-medium transition-all', active ? 'bg-[#1b6670] text-white shadow-[inset_3px_0_0_#f2b45f]' : 'text-[#a9c8c6] hover:bg-[#194850] hover:text-white')} data-testid={`link-nav-${item.href.slice(1)}`}>
              <span className="flex items-center gap-3"><Icon size={16} strokeWidth={active ? 2.2 : 1.7} />{item.label}</span>{item.count && <span className={cn('flex h-5 min-w-5 items-center justify-center rounded-full px-1 text-[10px]', active ? 'bg-[#f2b45f] text-[#193b3e]' : 'bg-[#244f55] text-[#b3d6d2]')}>{item.count}</span>}
            </Link>;
          })}</div></div>)}
        </nav>
        <div className="absolute bottom-5 left-3 right-3 rounded-2xl border border-[#2a5960] bg-[#173f47] p-3.5">
          <div className="flex items-center gap-2 text-[11px] font-semibold text-[#dcefed]"><span className="h-2 w-2 rounded-full bg-[#62c89c] shadow-[0_0_0_4px_rgba(98,200,156,.12)]" /> Demo workspace</div>
          <p className="mt-2 text-[10px] leading-relaxed text-[#8db5b2]">All observations are simulated. Verify official advisories before action.</p>
        </div>
      </aside>
      {open && <button onClick={() => setOpen(false)} className="fixed inset-0 z-40 bg-[#09262d]/45 lg:hidden" aria-label="Close menu backdrop" data-testid="button-navigation-backdrop" />}
      <main className="min-h-[100dvh] pt-14 lg:pl-[236px]"><div className="mx-auto max-w-[1540px] p-4 sm:p-6 lg:p-8">{children}</div></main>
    </div>
  );
}

function PageTitle({ eyebrow, title, detail, action }) {
  return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mono mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#1d8085]">{eyebrow}</div><h1 className="text-[26px] font-bold tracking-[-.035em] text-[#163e45] sm:text-[32px]">{title}</h1>{detail && <p className="mt-1.5 max-w-2xl text-[13px] leading-relaxed text-[#698488]">{detail}</p>}</div>{action}</div>;
}

function Surface({ children, className = '' }) {
  return <section className={cn('rounded-2xl border border-[#d5e8e5] bg-white/85 shadow-[0_12px_35px_rgba(19,76,82,.055)]', className)}>{children}</section>;
}

function MiniLabel({ children }) { return <div className="mono text-[9px] font-bold uppercase tracking-[.16em] text-[#789296]">{children}</div>; }
function StatusPill({ children, tone = 'neutral' }) {
  const styles = { good: 'bg-[#e8f7ee] text-[#28744e]', signal: 'bg-[#e2f5f4] text-[#14717a]', warn: 'bg-[#fff2df] text-[#aa641f]', danger: 'bg-[#fce9e7] text-[#ad463f]', neutral: 'bg-[#eef4f3] text-[#5e7778]' };
  return <span className={cn('inline-flex items-center gap-1 rounded-full px-2 py-1 text-[10px] font-bold', styles[tone])}>{children}</span>;
}
function Spark({ data, color = teal }) {
  const points = data.map((value, i) => `${i * (100 / (data.length - 1))},${48 - ((value - Math.min(...data)) / (Math.max(...data) - Math.min(...data) || 1)) * 38}`);
  return <svg viewBox="0 0 100 50" className="h-10 w-24 overflow-visible"><polyline points={points.join(' ')} fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" /><circle cx={points.at(-1)?.split(',')[0]} cy={points.at(-1)?.split(',')[1]} r="2.5" fill={color} /></svg>;
}
function MetricCard({ icon: Icon, label, value, unit, change, data, tone = 'signal' }) {
  return <Surface className="animate-rise flex min-h-[139px] flex-col justify-between p-4"><div className="flex items-start justify-between"><div className={cn('flex h-8 w-8 items-center justify-center rounded-xl', tone === 'warn' ? 'bg-[#fff0dc] text-[#c07725]' : tone === 'good' ? 'bg-[#e4f5ee] text-[#2d8b60]' : 'bg-[#e2f3f2] text-[#16737c]')}><Icon size={16} /></div>{data && <Spark data={data} color={tone === 'warn' ? amber : teal} />}</div><div><MiniLabel>{label}</MiniLabel><div className="mt-1 flex items-baseline gap-1"><span className="text-[25px] font-bold tracking-[-.04em] text-[#183f45]">{value}</span>{unit && <span className="text-[11px] font-semibold text-[#789296]">{unit}</span>}</div>{change && <div className="mt-1 flex items-center gap-1 text-[10px] font-semibold text-[#5f8580]"><ArrowUpRight size={12} /> {change}</div>}</div></Surface>;
}

const markerIcon = (label, tone) => L.divIcon({
  className: 'orca-leaflet-marker',
  html: `<span class="orca-marker ${tone}">${label}</span>`,
  iconSize: [42, 42],
  iconAnchor: [21, 21],
});

function LeafletControls({ onLocate, locating }) {
  const map = useMap();
  return <>
    <div className="leaflet-toolbar absolute left-4 top-4 z-[1000] flex flex-wrap gap-2">
      <button onClick={() => map.zoomIn()} className="rounded-xl border border-[#b6d6d2] bg-white/95 px-3 py-2 text-[10px] font-bold text-[#286b70] shadow-sm" data-testid="button-map-zoom-in">+</button>
      <button onClick={() => map.zoomOut()} className="rounded-xl border border-[#b6d6d2] bg-white/95 px-3 py-2 text-[10px] font-bold text-[#286b70] shadow-sm" data-testid="button-map-zoom-out">−</button>
      <button onClick={onLocate} className="flex items-center gap-1.5 rounded-xl border border-[#b6d6d2] bg-white/95 px-3 py-2 text-[10px] font-bold text-[#286b70] shadow-sm" data-testid="button-map-locate"><LocateFixed size={13} /> {locating ? 'Locating…' : 'Vessel'}</button>
    </div>
  </>;
}

function SimulatedMap({ route = false, onZone }) {
  const [layers, setLayers] = useState({ pfz: true, risk: true, alerts: true });
  const [selected, setSelected] = useState(null);
  const [locating, setLocating] = useState(false);
  const [vesselPosition, setVesselPosition] = useState(mapProvider.center);
  const locate = async () => {
    setLocating(true);
    const position = await locationService.locate();
    setVesselPosition([position.lat, position.lng]);
    setLocating(false);
  };
  const toggleLayer = (layer) => setLayers((state) => ({ ...state, [layer]: !state[layer] }));
  return <div className="relative min-h-[390px] overflow-hidden rounded-2xl border border-[#bddbd7] bg-[#cbe8e3] sm:min-h-[510px]">
    <MapContainer center={mapProvider.center} zoom={mapProvider.zoom} scrollWheelZoom className="h-full min-h-[390px] w-full sm:min-h-[510px]" zoomControl={false}>
      <TileLayer url={mapProvider.tileUrl} attribution={mapProvider.attribution} />
      <LeafletControls onLocate={locate} locating={locating} />
      {layers.pfz && pfzZones.map((zone) => <Marker key={zone.id} position={[zone.lat, zone.lng]} icon={markerIcon(zone.score, 'pfz')} eventHandlers={{ click: () => { setSelected(zone); onZone?.(zone); } }}><Popup><div className="min-w-[150px] text-[#315d62]"><b>{zone.name}</b><br /><span>Potential score {zone.score} · {zone.confidence}% confidence</span><br /><small>{zone.species}</small></div></Popup></Marker>)}
      {layers.risk && <><Circle center={[18.6, 72.66]} radius={7200} pathOptions={{ color: '#e79136', fillColor: '#e79136', fillOpacity: 0.16, weight: 2, dashArray: '7 7' }} /><Polygon positions={[[18.72,72.48],[18.86,72.7],[18.67,72.82],[18.52,72.68]]} pathOptions={{ color: '#d6a05a', fillColor: '#f1b760', fillOpacity: 0.08, weight: 1 }}><Popup><b>Moderate swell transition</b><br />Estimated to build after 16:00.</Popup></Polygon></>}
      {layers.alerts && <Marker position={[18.73,72.72]} icon={markerIcon('!', 'alert')}><Popup><b>Watch: swell building</b><br />Review timing before departure.</Popup></Marker>}
      <Marker position={vesselPosition} icon={markerIcon('V', 'vessel')}><Popup><b>Current vessel</b><br />18.52° N · 72.85° E</Popup></Marker>
      {route && <Polyline positions={routePoints.map((point) => [point.lat, point.lng])} pathOptions={{ color: '#e79136', weight: 4, dashArray: '9 7' }}><Popup><b>Estimated route</b><br />41.8 nm · 3 h 12 min</Popup></Polyline>}
    </MapContainer>
    <div className="absolute left-4 top-[62px] z-[1000] flex overflow-hidden rounded-xl border border-[#b6d6d2] bg-white/95 shadow-sm"><span className="px-3 py-2 text-[9px] font-bold uppercase tracking-wider text-[#7d9693]">Layers</span>{['pfz', 'risk', 'alerts'].map((layer) => <button key={layer} onClick={() => toggleLayer(layer)} className={cn('border-l border-[#d4e7e4] px-3 py-2 text-[9px] font-bold uppercase tracking-wider', layers[layer] ? 'bg-[#f2faf8] text-[#176c74]' : 'bg-white text-[#91a7a6]')} data-testid={`button-layer-${layer}`}><span className={cn('mr-1.5 inline-block h-1.5 w-1.5 rounded-full', layer === 'pfz' ? 'bg-[#1b8b87]' : layer === 'risk' ? 'bg-[#e79136]' : 'bg-[#d85e52]')} />{layer}</button>)}</div>
    <div className="pointer-events-none absolute bottom-4 left-4 z-[1000] rounded-xl border border-[#c8e0dc] bg-white/90 px-3 py-2 text-[10px] text-[#517174] shadow-sm"><span className="mono font-bold text-[#285c64]">18.52° N · 72.85° E</span><span className="mx-2 text-[#b1c5c2]">|</span> Arabian Sea <span className="ml-2 text-[#9aafad]">OSM · zoom {mapProvider.zoom}</span></div>
    {selected && <div className="absolute bottom-4 left-1/2 z-[1100] w-[calc(100%-2rem)] max-w-[300px] -translate-x-1/2 rounded-2xl border border-[#b9ddd7] bg-[#f9fffd]/95 p-3.5 shadow-xl backdrop-blur"><button onClick={() => setSelected(null)} className="absolute right-2 top-2 text-[#71908e]" aria-label="Close zone detail" data-testid="button-close-zone-detail"><X size={14} /></button><MiniLabel>Selected intelligence zone</MiniLabel><div className="mt-1 text-[14px] font-bold text-[#1c555c]">{selected.name}</div><div className="mt-2 grid grid-cols-3 gap-2 text-[10px]"><div><MiniLabel>Score</MiniLabel><b className="text-[15px] text-[#14717a]">{selected.score}</b></div><div><MiniLabel>Confidence</MiniLabel><b className="text-[15px] text-[#14717a]">{selected.confidence}%</b></div><div><MiniLabel>Distance</MiniLabel><b className="text-[15px] text-[#14717a]">{selected.distance}</b></div></div><p className="mt-2 text-[10px] text-[#648180]">{selected.species}</p></div>}
  </div>;
}

function SectionHeader({ title, action }) { return <div className="mb-4 flex items-center justify-between"><h2 className="text-[14px] font-bold text-[#214e55]">{title}</h2>{action}</div>; }
function EmptyState({ title, detail, icon: Icon = Database }) { return <div className="flex min-h-[220px] flex-col items-center justify-center rounded-2xl border border-dashed border-[#c8dfdc] bg-[#f5fbfa] p-8 text-center"><div className="mb-3 flex h-11 w-11 items-center justify-center rounded-2xl bg-[#dff0ed] text-[#2c7f82]"><Icon size={20} /></div><h3 className="text-[14px] font-bold text-[#315b60]">{title}</h3><p className="mt-1 max-w-xs text-[11px] leading-relaxed text-[#789193]">{detail}</p></div>; }

function Dashboard() {
  return <div className="animate-rise">
    <PageTitle eyebrow="Mission overview / 01" title="Good morning, Aakash." detail="A cautious read of conditions around Mumbai coast, prepared for your next decision." action={<div className="flex items-center gap-2"><button className="flex items-center gap-2 rounded-xl border border-[#c9dfdc] bg-white px-3 py-2.5 text-[11px] font-bold text-[#28656a] hover:bg-[#f4fbfa]" data-testid="button-refresh-dashboard"><RefreshCw size={14} /> Refresh blend</button><Link href="/map" className="flex items-center gap-2 rounded-xl bg-[#126972] px-3 py-2.5 text-[11px] font-bold text-white shadow-sm hover:bg-[#0d5961]" data-testid="link-open-map"><MapIcon size={14} /> Open map</Link></div>} />
    <div className="mb-6 flex items-center gap-2 rounded-xl border border-[#d3e8e4] bg-[#f8fdfb] px-3 py-2.5 text-[11px] text-[#647f80]"><span className="flex h-5 w-5 items-center justify-center rounded-full bg-[#d9efea] text-[#20747b]"><Radio size={12} /></span><b className="text-[#2b6266]">Live demo blend</b><span>Satellite, buoy and forecast layers are simulated for presentation.</span><span className="ml-auto hidden mono text-[9px] text-[#91a5a3] sm:block">LAST SYNC {dashboardSnapshot.updated}</span></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={Thermometer} label="Sea surface temperature" value={String(dashboardSnapshot.seaTemp)} unit="°C" change="0.4° above seasonal" data={marineConditions.seaTemp} /><MetricCard icon={Wind} label="Wind / WSW" value={String(dashboardSnapshot.wind)} unit="kn" change="gusts up to 21 kn" data={[8, 10, 12, 14, 16, 15, 14]} tone="warn" /><MetricCard icon={Fish} label="PFZ potential" value={String(dashboardSnapshot.pfzScore)} unit="/ 100" change="74% model confidence" data={[58, 64, 61, 69, 74, 78, 78]} /><MetricCard icon={Shield} label="Composite risk" value={String(dashboardSnapshot.riskIndex)} unit="/ 100" change="Moderate · review swell" data={[22, 25, 28, 27, 29, 31, 31]} tone="warn" /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.8fr]"><Surface className="overflow-hidden"><div className="flex items-center justify-between border-b border-[#e0eeeb] px-5 py-4"><div><MiniLabel>Spatial intelligence</MiniLabel><h2 className="mt-1 text-[16px] font-bold text-[#204d53]">What the sea is telling us</h2></div><Link href="/map" className="flex items-center gap-1 text-[11px] font-bold text-[#20747b]" data-testid="link-map-expand">Expand map <ChevronRight size={14} /></Link></div><div className="p-3"><SimulatedMap /></div></Surface>
      <div className="space-y-5"><Surface className="p-5"><SectionHeader title="Recommended next move" action={<Sparkles size={16} className="text-[#d88b32]" />} /><div className="flex items-start gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#fff0d9] text-[#c57927]"><Compass size={18} /></div><div><StatusPill tone="warn">Proceed with caution</StatusPill><p className="mt-3 text-[13px] font-semibold leading-relaxed text-[#315b60]">{dashboardSnapshot.recommendationDetail}</p><Link href="/route" className="mt-4 inline-flex items-center gap-1.5 text-[11px] font-bold text-[#14717a]" data-testid="link-plan-route">Plan a route <ChevronRight size={13} /></Link></div></div></Surface>
        <Surface className="p-5"><SectionHeader title="Agent activity" action={<span className="flex items-center gap-1 text-[10px] text-[#7b9292]"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-[#3baf7d]" /> updating</span>} /><div className="space-y-4">{dashboardSnapshot.activity.map((activity) => <div key={activity.label} className="flex gap-3"><div className={cn('mt-1 h-2 w-2 shrink-0 rounded-full', activity.tone === 'warn' ? 'bg-[#e79136]' : activity.tone === 'signal' ? 'bg-[#289ba0]' : 'bg-[#55b881]')} /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2 text-[11px] font-bold text-[#41666a]"><span>{activity.label}</span><span className="mono text-[9px] font-normal text-[#91a8a5]">{activity.time}</span></div><div className="mt-0.5 text-[10px] text-[#809595]">{activity.detail}</div></div></div>)}</div></Surface></div></div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[1fr_1fr]"><Surface className="p-5"><SectionHeader title="Today at a glance" action={<Link href="/weather" className="text-[10px] font-bold text-[#20747b]" data-testid="link-weather-glance">Full forecast <ChevronRight size={12} className="inline" /></Link>} /><div className="grid grid-cols-3 gap-3">{[['06:00','28°','12 kn'],['12:00','31°','18 kn'],['18:00','29°','19 kn']].map(([time,temp,wind]) => <div key={time} className="rounded-xl bg-[#f1f8f7] p-3"><div className="mono text-[9px] text-[#75908f]">{time}</div><div className="mt-3 flex items-center gap-1.5 text-[17px] font-bold text-[#285d63]"><Wind size={14} className="text-[#d99035]" />{temp}</div><div className="mt-1 text-[10px] text-[#75908f]">{wind}</div></div>)}</div></Surface><Surface className="p-5"><SectionHeader title="Attention needed" action={<Link href="/alerts" className="text-[10px] font-bold text-[#20747b]" data-testid="link-alerts-glance">View all <ChevronRight size={12} className="inline" /></Link>} /><div className="space-y-2">{seedAlerts.slice(0, 2).map((alert) => <Link href="/alerts" key={alert.id} className="flex items-center gap-3 rounded-xl border border-[#e4eeeb] px-3 py-2.5 hover:bg-[#f4fbfa]" data-testid={`link-alert-${alert.id}`}><div className={cn('flex h-7 w-7 shrink-0 items-center justify-center rounded-lg', alert.type === 'marine' ? 'bg-[#fff0de] text-[#bd7226]' : 'bg-[#e8f5f2] text-[#18747b]')}><AlertTriangle size={13} /></div><div className="min-w-0 flex-1"><div className="truncate text-[11px] font-bold text-[#3b5f63]">{alert.title}</div><div className="mt-0.5 text-[9px] text-[#8a9e9d]">{alert.time}</div></div><ChevronRight size={14} className="text-[#9ab0ad]" /></Link>)}</div></Surface></div>
  </div>;
}

function MapPage() { return <div className="animate-rise"><PageTitle eyebrow="Spatial intelligence / 02" title="Intelligence map" detail="A layered view of estimated fishing potential, conditions and operational watch items." action={<button className="flex items-center gap-2 rounded-xl border border-[#c9dfdc] bg-white px-3 py-2.5 text-[11px] font-bold text-[#28656a]" data-testid="button-map-export"><Download size={14} /> Export view</button>} /><div className="grid gap-5 xl:grid-cols-[1fr_300px]"><SimulatedMap onZone={() => undefined} /><div className="space-y-5"><Surface className="p-5"><MiniLabel>Map context</MiniLabel><div className="mt-3 space-y-3">{[['Current vessel','18.52° N · 72.85° E','bg-[#145f6a]'],['Best PFZ','West shelf front · 86','bg-[#42a993]'],['Risk watch','Swell transition','bg-[#e79136]'],['Alert','1 active watch','bg-[#d96858]']].map(([name,value,color]) => <div key={name} className="flex items-center gap-3"><span className={cn('h-2.5 w-2.5 rounded-full', color)} /><div><div className="text-[11px] font-bold text-[#45696c]">{name}</div><div className="mono text-[9px] text-[#819795]">{value}</div></div></div>)}</div></Surface><Surface className="p-5"><SectionHeader title="Selected layers" /><div className="space-y-2 text-[11px] text-[#607d7e]"><div className="flex items-center justify-between"><span className="flex items-center gap-2"><Layers size={14} /> PFZ zones</span><span className="mono text-[10px]">3 zones</span></div><div className="flex items-center justify-between"><span className="flex items-center gap-2"><Shield size={14} /> Risk surface</span><span className="mono text-[10px]">24 h</span></div><div className="flex items-center justify-between"><span className="flex items-center gap-2"><Bell size={14} /> Alerts</span><span className="mono text-[10px]">1 watch</span></div></div></Surface><div className="rounded-2xl border border-[#f0dfc4] bg-[#fff8ed] p-4 text-[10px] leading-relaxed text-[#8e652f]"><b className="text-[#9d6823]">Navigation note</b><br />Map layers are illustrative. Coordinates and route guidance must be verified against official nautical sources.</div></div></div></div>; }

function PfzPage() {
  const [selected, setSelected] = useState(pfzZones[0]);
  const chartData = [{ hour: '00', score: 59, chlorophyll: 43 }, { hour: '04', score: 66, chlorophyll: 48 }, { hour: '08', score: 72, chlorophyll: 56 }, { hour: '12', score: 86, chlorophyll: 68 }, { hour: '16', score: 81, chlorophyll: 62 }, { hour: '20', score: 74, chlorophyll: 59 }, { hour: '24', score: 70, chlorophyll: 55 }];
  return <div className="animate-rise"><PageTitle eyebrow="Potential fishing zones / 03" title="PFZ intelligence" detail="Understand why a zone is being surfaced before deciding whether it fits your operation." action={<StatusPill tone="signal"><Signal size={12} /> Model refreshed 06:35</StatusPill>} /><div className="grid gap-5 xl:grid-cols-[1fr_1.05fr]"><Surface className="p-5"><SectionHeader title="Zone candidates" action={<span className="mono text-[9px] text-[#859b99]">3 ACTIVE</span>} /><div className="space-y-2">{pfzZones.map((zone, index) => <button onClick={() => setSelected(zone)} key={zone.id} className={cn('w-full rounded-xl border p-3.5 text-left transition-all', selected.id === zone.id ? 'border-[#76bdb5] bg-[#edf9f6] shadow-sm' : 'border-[#e2eeec] bg-white hover:border-[#b9d9d5]')} data-testid={`button-select-${zone.id}`}><div className="flex items-start justify-between"><div><div className="flex items-center gap-2 text-[12px] font-bold text-[#315d62]"><span className="mono text-[10px] text-[#8ea5a1]">0{index + 1}</span>{zone.name}</div><div className="mt-1 text-[10px] text-[#77908e]">{zone.species}</div></div><div className="text-right"><div className="text-[22px] font-bold tracking-tight text-[#14717a]">{zone.score}</div><div className="mono text-[8px] uppercase text-[#829997]">potential</div></div></div><div className="mt-3 flex items-center gap-2"><div className="h-1.5 flex-1 overflow-hidden rounded-full bg-[#dcece8]"><div className="h-full rounded-full bg-[#3ea692]" style={{ width: `${zone.score}%` }} /></div><span className="mono text-[9px] text-[#6e8987]">{zone.confidence}% confidence</span></div></button>)}</div></Surface><Surface className="p-5"><div className="flex items-start justify-between"><div><MiniLabel>Selected zone / {selected.distance} offshore</MiniLabel><h2 className="mt-1 text-[19px] font-bold text-[#204e55]">{selected.name}</h2><p className="mt-1 text-[11px] text-[#7c9492]">An estimate from temperature, chlorophyll and front geometry.</p></div><div className="rounded-xl bg-[#e4f5f0] px-3 py-2 text-center"><div className="text-[24px] font-bold text-[#15757b]">{selected.score}</div><div className="mono text-[8px] uppercase text-[#65918d]">score</div></div></div><div className="mt-6 h-[220px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><defs><linearGradient id="pfzFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#43a99c" stopOpacity=".28" /><stop offset="1" stopColor="#43a99c" stopOpacity=".02" /></linearGradient></defs><CartesianGrid stroke="#e5efed" vertical={false} /><XAxis dataKey="hour" tick={{ fontSize: 10, fill: '#829b98' }} axisLine={false} tickLine={false} /><YAxis domain={[0, 100]} tick={{ fontSize: 10, fill: '#829b98' }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #d5e8e5', fontSize: 11 }} /><Area type="monotone" dataKey="score" stroke="#258c87" fill="url(#pfzFill)" strokeWidth={2.5} /><Line type="monotone" dataKey="chlorophyll" stroke="#e79136" strokeWidth={2} dot={false} /></AreaChart></ResponsiveContainer></div><div className="mt-3 flex gap-4 text-[10px] text-[#738c8a]"><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full bg-[#258c87]" />Potential score</span><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full bg-[#e79136]" />Chlorophyll index</span></div><div className="mt-5 grid grid-cols-3 gap-2">{[['Depth', selected.depth], ['Species signal', selected.species.split(' · ')[0]], ['Approach', 'From east']].map(([a,b]) => <div key={a} className="rounded-xl bg-[#f2f8f7] p-3"><MiniLabel>{a}</MiniLabel><div className="mt-1 truncate text-[11px] font-bold text-[#41676a]">{b}</div></div>)}</div></Surface></div><div className="mt-5 rounded-2xl border border-[#f0dfc4] bg-[#fff8ed] p-4 text-[11px] leading-relaxed text-[#8b6835]"><b className="text-[#9c6a27]">Interpretation guardrail:</b> PFZ signals estimate environmental suitability, not catch certainty. Conditions may change between the model refresh and arrival.</div></div>;
}

function WeatherPage() {
  return <div className="animate-rise"><PageTitle eyebrow="Atmosphere & sea state / 04" title="Weather & sea" detail="A compact operating forecast for the Mumbai coast demo area." action={<div className="flex items-center gap-2"><StatusPill tone="good"><span className="h-1.5 w-1.5 rounded-full bg-[#38a56f]" /> Forecast blended</StatusPill></div>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard icon={Thermometer} label="Air temperature" value="29" unit="°C" change="Feels like 31°" data={[28, 29, 30, 31, 31, 30]} /><MetricCard icon={Wind} label="Wind / WSW" value="14" unit="kn" change="Gusts 21 kn" data={[11, 12, 14, 16, 19, 18]} tone="warn" /><MetricCard icon={Waves} label="Significant swell" value="1.1" unit="m" change="Building after 16:00" data={[.8, .9, 1.1, 1.3, 1.5, 1.4]} tone="warn" /><MetricCard icon={Activity} label="Visibility" value="8.2" unit="km" change="Good for current window" data={[8.6, 8.4, 8.2, 8, 8.1, 8.2]} tone="good" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_.75fr]"><Surface className="p-5"><SectionHeader title="Next 18 hours" action={<span className="mono text-[9px] text-[#879c99]">IST · 06 JUN</span>} /><div className="h-[280px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={weatherData.hourly}><CartesianGrid stroke="#e5efed" vertical={false} /><XAxis dataKey="time" tick={{ fontSize: 10, fill: '#829b98' }} axisLine={false} tickLine={false} /><YAxis yAxisId="temp" tick={{ fontSize: 10, fill: '#829b98' }} axisLine={false} tickLine={false} /><YAxis yAxisId="wind" orientation="right" tick={{ fontSize: 10, fill: '#829b98' }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #d5e8e5', fontSize: 11 }} /><Line yAxisId="temp" type="monotone" dataKey="temp" stroke="#df8b32" strokeWidth={2.5} dot={{ r: 3, fill: '#df8b32' }} /><Line yAxisId="wind" type="monotone" dataKey="wind" stroke="#1b858a" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div><div className="flex gap-5 text-[10px] text-[#738c8a]"><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full bg-[#df8b32]" />Temperature °C</span><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full bg-[#1b858a]" />Wind knots</span></div></Surface><Surface className="p-5"><SectionHeader title="Current reading" /><div className="flex items-center gap-3 rounded-xl bg-[#eef8f6] p-4"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#d6ece8] text-[#267c80]"><Wind size={22} /></div><div><div className="text-[19px] font-bold text-[#315c61]">WSW 14 kn</div><div className="text-[10px] text-[#75908d]">Moderate breeze · 248°</div></div></div><div className="mt-4 space-y-3">{[['Humidity','76%'],['Pressure','1008 hPa'],['Rain chance','18%'],['Visibility','8.2 km']].map(([a,b]) => <div key={a} className="flex justify-between border-b border-[#edf3f1] pb-2 text-[11px]"><span className="text-[#829896]">{a}</span><b className="text-[#47696c]">{b}</b></div>)}</div><div className="mt-4 rounded-xl bg-[#fff8ed] p-3 text-[10px] leading-relaxed text-[#906931]"><AlertTriangle size={13} className="mr-1 inline" /> Swell is the notable change to monitor this afternoon.</div></Surface></div></div>;
}

function RiskPage() { return <div className="animate-rise"><PageTitle eyebrow="Decision confidence / 05" title="Explainable risk" detail="See the factors behind the score, not just the score itself." action={<div className="flex items-center gap-2 rounded-xl bg-[#fff2df] px-3 py-2 text-[11px] font-bold text-[#a56524]"><Shield size={14} /> Moderate · 31 / 100</div>} /><div className="grid gap-5 xl:grid-cols-[.72fr_1.28fr]"><Surface className="flex flex-col items-center justify-center p-7"><div className="relative flex h-52 w-52 items-center justify-center rounded-full" style={{ background: 'conic-gradient(#e79136 0 31%, #e7f0ec 31% 100%)' }}><div className="flex h-40 w-40 flex-col items-center justify-center rounded-full bg-white"><div className="text-[48px] font-bold tracking-[-.06em] text-[#254f55]">31</div><div className="mono text-[9px] uppercase tracking-widest text-[#8ca09e]">out of 100</div></div></div><StatusPill tone="warn">Moderate exposure</StatusPill><p className="mt-4 max-w-xs text-center text-[11px] leading-relaxed text-[#718988]">The score is an estimate from available weather and marine signals. It is not a safety clearance.</p></Surface><Surface className="p-5"><SectionHeader title="What is shaping the score" action={<span className="mono text-[9px] text-[#839a97]">WEIGHTED SIGNALS</span>} /><div className="space-y-4">{riskFactors.map((factor) => <div key={factor.id}><div className="flex items-center justify-between"><div><div className="text-[12px] font-bold text-[#456a6d]">{factor.label}</div><div className="mt-0.5 text-[10px] text-[#859a98]">{factor.detail}</div></div><div className="text-right"><div className="text-[12px] font-bold text-[#bf7629]">{factor.value}</div><div className="mono text-[9px] text-[#91a5a2]">{factor.status}</div></div></div><div className="mt-2 h-2 rounded-full bg-[#edf2ef]"><div className={cn('h-full rounded-full', factor.score > 35 ? 'bg-[#e79136]' : 'bg-[#62aa94]')} style={{ width: `${factor.score * 1.7}%` }} /></div></div>)}</div><div className="mt-5 flex items-start gap-2 rounded-xl border border-[#d9e9e5] bg-[#f5fbf9] p-3 text-[10px] leading-relaxed text-[#668281]"><CircleHelp size={14} className="mt-0.5 shrink-0 text-[#32878a]" />Scores combine simulated observations for demonstration. Confirm actual sea state, notices and vessel capability before proceeding.</div></Surface></div></div>; }

function RoutePage() { const [calculated, setCalculated] = useState(false); return <div className="animate-rise"><PageTitle eyebrow="Operational planning / 06" title="Route planner" detail="Draft a route from your current position to an estimated intelligence zone." action={<button onClick={() => setCalculated(true)} className="flex items-center gap-2 rounded-xl bg-[#126972] px-3.5 py-2.5 text-[11px] font-bold text-white shadow-sm hover:bg-[#0d5961]" data-testid="button-calculate-route"><RouteIcon size={14} /> {calculated ? 'Recalculate route' : 'Calculate route'}</button>} /><div className="grid gap-5 xl:grid-cols-[1fr_340px]"><div className="relative"><SimulatedMap route /><div className="absolute bottom-5 left-5 rounded-xl border border-[#f0d9b7] bg-[#fff8ed]/95 px-3 py-2 text-[10px] text-[#91652d] shadow-sm"><span className="mr-1.5 inline-block h-2 w-2 rounded-full bg-[#e79136]" /> Estimated route · west shelf front</div></div><div className="space-y-5"><Surface className="p-5"><SectionHeader title="Route inputs" /><div className="space-y-3"><label className="block"><MiniLabel>Departure</MiniLabel><div className="mt-1 flex items-center gap-2 rounded-xl border border-[#d6e7e4] bg-[#f8fcfb] px-3 py-2.5 text-[11px] text-[#4d7173]"><Navigation size={14} className="text-[#24777a]" /> Current vessel position</div></label><label className="block"><MiniLabel>Destination</MiniLabel><select className="mt-1 w-full rounded-xl border border-[#d6e7e4] bg-[#f8fcfb] px-3 py-2.5 text-[11px] text-[#4d7173] outline-none" defaultValue="pfz-01" data-testid="select-route-destination">{pfzZones.map((zone) => <option key={zone.id} value={zone.id}>{zone.name} · score {zone.score}</option>)}</select></label><label className="block"><MiniLabel>Vessel profile</MiniLabel><select className="mt-1 w-full rounded-xl border border-[#d6e7e4] bg-[#f8fcfb] px-3 py-2.5 text-[11px] text-[#4d7173] outline-none" defaultValue="coastal" data-testid="select-vessel-profile"><option value="coastal">Coastal trawler · 13 kn</option><option value="small">Small craft · 9 kn</option></select></label></div></Surface><Surface className="p-5"><SectionHeader title="Estimated summary" action={calculated ? <Check size={15} className="text-[#39a070]" /> : undefined} /><div className="grid grid-cols-2 gap-2">{[['Distance', routeSummary.distance],['Travel time', routeSummary.duration],['Fuel estimate', routeSummary.fuel],['Safety read', routeSummary.safety]].map(([a,b]) => <div key={a} className="rounded-xl bg-[#f1f8f6] p-3"><MiniLabel>{a}</MiniLabel><div className="mt-1 text-[14px] font-bold text-[#3b6165]">{b}</div></div>)}</div><div className="mt-4 flex items-center gap-3 border-t border-[#e6efed] pt-4 text-[10px] text-[#7b9190]"><Timer size={14} /> Depart {routeSummary.departure} <ChevronRight size={13} /> ETA {routeSummary.arrival}</div></Surface><div className="rounded-2xl border border-[#f0dfc4] bg-[#fff8ed] p-4 text-[10px] leading-relaxed text-[#8e652f]"><b>Route caution:</b> This route is a planning estimate and does not account for traffic, restricted areas or live notices.</div></div></div></div>; }

function AlertsPage() { const [filter, setFilter] = useState('All'); const [items, setItems] = useState(seedAlerts); const visible = filter === 'All' ? items : items.filter((a) => a.type === filter.toLowerCase()); return <div className="animate-rise"><PageTitle eyebrow="Operational awareness / 07" title="Alert center" detail="A simulated stream of changes worth reviewing before you act." action={<button onClick={() => setItems((all) => all.map((a) => ({ ...a, read: true })))} className="flex items-center gap-2 rounded-xl border border-[#c9dfdc] bg-white px-3 py-2.5 text-[11px] font-bold text-[#28656a]" data-testid="button-mark-alerts-read"><Check size={14} /> Mark all read</button>} /><div className="mb-5 flex flex-wrap gap-2">{['All','Marine','PFZ','Safety','System'].map((item) => <button key={item} onClick={() => setFilter(item)} className={cn('rounded-full border px-3.5 py-2 text-[10px] font-bold transition-colors', filter === item ? 'border-[#287e81] bg-[#e3f4f1] text-[#176d73]' : 'border-[#d5e6e3] bg-white text-[#78908f] hover:bg-[#f2f9f7]')} data-testid={`button-alert-filter-${item.toLowerCase()}`}>{item}{item === 'All' && <span className="ml-1.5 text-[#a2b5b2]">{items.length}</span>}</button>)}</div><Surface className="overflow-hidden">{visible.length ? <div>{visible.map((alert) => <div key={alert.id} className={cn('flex gap-4 border-b border-[#e6efed] p-5 last:border-0', !alert.read && 'bg-[#fbfefd]')}><div className={cn('mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl', alert.type === 'marine' ? 'bg-[#fff0dd] text-[#bf7427]' : alert.type === 'safety' ? 'bg-[#fce9e7] text-[#b54f48]' : 'bg-[#e3f4f1] text-[#1a777d]')}><AlertTriangle size={17} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-[13px] font-bold text-[#315a60]">{alert.title}</h3>{!alert.read && <span className="h-1.5 w-1.5 rounded-full bg-[#e79136]" />}</div><p className="mt-1.5 max-w-2xl text-[11px] leading-relaxed text-[#78908f]">{alert.detail}</p><div className="mt-3 flex items-center gap-3"><StatusPill tone={alert.type === 'safety' ? 'danger' : alert.type === 'marine' ? 'warn' : 'signal'}>{alert.severity}</StatusPill><span className="mono text-[9px] text-[#98aaa7]">{alert.id} · {alert.time}</span></div></div><button onClick={() => setItems((all) => all.map((a) => a.id === alert.id ? { ...a, read: true } : a))} className="self-start rounded-lg p-1.5 text-[#9bb0ad] hover:bg-[#edf5f3] hover:text-[#387074]" aria-label={`Mark ${alert.id} read`} data-testid={`button-read-${alert.id}`}><Check size={15} /></button></div>)}</div> : <EmptyState title="No alerts in this view" detail="Try another filter. A quiet stream is useful information too." icon={Bell} />}</Surface></div>; }

function AssistantPage() { const suggestions = ['Where is the best fishing area?', 'What is the risk today?', 'Is the route safe?']; const [messages, setMessages] = useState([{ from: 'orca', text: 'I can help interpret the current demo blend. Ask about PFZ potential, risk, weather or a planned route.' }]); const [input, setInput] = useState(''); const send = (text = input) => { if (!text.trim()) return; const normalized = text.toLowerCase(); const key = Object.keys(assistantReplies).find((candidate) => candidate !== 'default' && normalized.includes(candidate)) || 'default'; setMessages((current) => [...current, { from: 'you', text }, { from: 'orca', text: assistantReplies[key] }]); setInput(''); }; return <div className="animate-rise"><PageTitle eyebrow="Decision companion / 08" title="Ask ORCA" detail="A transparent assistant for exploring the demo data, not a substitute for local expertise." action={<StatusPill tone="signal"><Sparkles size={12} /> Demo reasoning</StatusPill>} /><div className="grid gap-5 xl:grid-cols-[1fr_310px]"><Surface className="flex min-h-[560px] flex-col overflow-hidden"><div className="flex items-center gap-3 border-b border-[#e2eeeb] bg-[#f7fcfb] px-5 py-4"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#d9efeb] text-[#176f77]"><Bot size={18} /></div><div><div className="text-[13px] font-bold text-[#315a60]">ORCA reasoning layer</div><div className="flex items-center gap-1.5 text-[10px] text-[#7c9693]"><span className="h-1.5 w-1.5 rounded-full bg-[#48ab7e]" /> Available on demo data</div></div></div><div className="scrollbar-thin flex-1 space-y-4 overflow-y-auto p-5">{messages.map((message, index) => <div key={`${message.from}-${index}`} className={cn('flex max-w-[88%] gap-2.5', message.from === 'you' && 'ml-auto flex-row-reverse')}><div className={cn('mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full', message.from === 'you' ? 'bg-[#e6eef0] text-[#557276]' : 'bg-[#d9efeb] text-[#176f77]')}>{message.from === 'you' ? <div className="text-[10px] font-bold">AK</div> : <Bot size={14} />}</div><div className={cn('rounded-2xl px-3.5 py-3 text-[11px] leading-relaxed', message.from === 'you' ? 'rounded-tr-sm bg-[#e7f2f1] text-[#42676b]' : 'rounded-tl-sm bg-[#f3f8f7] text-[#5c7778]')}>{message.text}</div></div>)}</div><div className="border-t border-[#e2eeeb] p-4"><div className="flex gap-2">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => send(suggestion)} className="hidden rounded-full border border-[#cfe4e0] px-3 py-1.5 text-[9px] font-bold text-[#4d7b7b] hover:bg-[#edf8f5] sm:block" data-testid={`button-suggestion-${suggestion.slice(0,5).replaceAll(' ','-').toLowerCase()}`}>{suggestion}</button>)}</div><div className="mt-3 flex items-center gap-2 rounded-xl border border-[#c9dfdc] bg-white p-1.5 focus-within:border-[#4a9a98]"><input value={input} onChange={(event) => setInput(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') send(); }} placeholder="Ask about conditions, risk or a zone…" className="min-w-0 flex-1 bg-transparent px-2 text-[11px] text-[#456b6d] outline-none placeholder:text-[#9bb0ad]" data-testid="input-assistant-message" /><button onClick={() => send()} className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#176f77] text-white hover:bg-[#105e66]" aria-label="Send message" data-testid="button-send-assistant"><Send size={14} /></button></div></div></Surface><div className="space-y-5"><Surface className="p-5"><SectionHeader title="Try asking" /><div className="space-y-2">{suggestions.map((suggestion) => <button key={suggestion} onClick={() => send(suggestion)} className="flex w-full items-center justify-between rounded-xl border border-[#e1ece9] p-3 text-left text-[11px] font-semibold text-[#4e7172] hover:border-[#9bcac2] hover:bg-[#f3faf8]" data-testid={`button-try-${suggestion.slice(0,5).replaceAll(' ','-').toLowerCase()}`}>{suggestion}<ChevronRight size={14} className="text-[#8dadab]" /></button>)}</div></Surface><div className="rounded-2xl border border-[#f0dfc4] bg-[#fff8ed] p-4 text-[10px] leading-relaxed text-[#8d672f]"><Info size={14} className="mb-2 text-[#c47d2e]" /><b>How to read answers</b><br />ORCA will show what the data suggests and where uncertainty remains. Verify official advisories.</div></div></div></div>; }

function OfflinePage() { const [saved, setSaved] = useState(Boolean(cacheService.read())); const [saving, setSaving] = useState(false); const save = () => { setSaving(true); setTimeout(() => { cacheService.save({ dashboardSnapshot, pfzZones, riskFactors }); setSaved(true); setSaving(false); }, 650); }; return <div className="animate-rise"><PageTitle eyebrow="Continuity / 09" title="Offline continuity" detail="Keep a compact decision context available when the signal drops." action={<StatusPill tone={saved ? 'good' : 'neutral'}>{saved ? <Check size={12} /> : <Database size={12} />} {saved ? 'Snapshot available' : 'No snapshot yet'}</StatusPill>} /><div className="grid gap-5 xl:grid-cols-[1fr_340px]"><Surface className="p-6"><div className="flex items-start gap-4"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#e2f2ef] text-[#27797c]"><Database size={22} /></div><div><h2 className="text-[17px] font-bold text-[#315d62]">Local demo cache</h2><p className="mt-1 max-w-lg text-[12px] leading-relaxed text-[#718a89]">A browser-local snapshot preserves the last dashboard blend, PFZ candidates and risk factors. It never claims to be live while offline.</p></div></div><div className="mt-7 grid gap-3 sm:grid-cols-3">{[['Dashboard blend','Available'],['PFZ intelligence','Available'],['Alerts','Last seen']].map(([a,b]) => <div key={a} className="rounded-xl border border-[#e0ece9] bg-[#f7fbfa] p-4"><MiniLabel>{a}</MiniLabel><div className="mt-2 flex items-center gap-1.5 text-[11px] font-bold text-[#41806f]"><Check size={13} /> {b}</div></div>)}</div><button onClick={save} disabled={saving} className="mt-6 flex items-center gap-2 rounded-xl bg-[#126972] px-4 py-3 text-[11px] font-bold text-white disabled:opacity-70" data-testid="button-save-snapshot">{saving ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />} {saving ? 'Saving snapshot…' : 'Save current snapshot'}</button></Surface><div className="space-y-5"><Surface className="p-5"><SectionHeader title="Offline checklist" /><div className="space-y-3 text-[11px] text-[#65807f]">{['Last known vessel position','PFZ scores and confidence','Risk factors and cautions','Alert history'].map((item) => <div key={item} className="flex items-center gap-2"><Check size={14} className="text-[#45a176]" />{item}</div>)}</div></Surface><div className="rounded-2xl border border-[#cce2df] bg-[#eef8f5] p-4 text-[10px] leading-relaxed text-[#5f7e7d]"><WifiOff size={14} className="mb-2 text-[#317b80]" /><b className="text-[#3e6769]">Continuity, not autonomy.</b><br />Cached information can age quickly. Reconnect before making an operational decision.</div></div></div></div>; }

function AboutPage() { return <div className="animate-rise"><PageTitle eyebrow="Project context / 10" title="About ORCA" detail="A presentation-ready concept for marine ecosystem intelligence in the SIH 2026 challenge." /><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><Surface className="p-6 sm:p-8"><div className="mono text-[10px] font-bold uppercase tracking-[.18em] text-[#1d8085]">The idea</div><h2 className="mt-3 max-w-2xl text-[26px] font-bold leading-tight tracking-[-.04em] text-[#204e55]">Make a complex ocean legible before it becomes urgent.</h2><p className="mt-4 max-w-2xl text-[13px] leading-7 text-[#688281]">ORCA brings marine conditions, potential fishing zones, risk signals, alerts and planning context into one calm operational view. The goal is not to replace experience, but to give it a better starting point.</p><div className="mt-8 grid gap-3 sm:grid-cols-3">{[['01','Observe','Blend the available signals.'],['02','Explain','Show why a signal matters.'],['03','Decide','Keep the final call human.']].map(([number,title,detail]) => <div key={number} className="rounded-2xl bg-[#f0f8f6] p-4"><div className="mono text-[10px] text-[#d58b39]">{number}</div><div className="mt-5 text-[13px] font-bold text-[#3e6669]">{title}</div><p className="mt-1 text-[10px] leading-relaxed text-[#7b9290]">{detail}</p></div>)}</div></Surface><div className="space-y-5"><Surface className="p-5"><SectionHeader title="Demo boundaries" /><div className="space-y-3 text-[11px] leading-relaxed text-[#708887]">{['All observations are simulated and designed for interface demonstration.','No live satellite, buoy, AIS or official advisory feeds are connected.','PFZ and route outputs are estimates, not guarantees or navigation directions.','Always verify local rules, vessel capability and official notices.'].map((item) => <div key={item} className="flex gap-2"><Info size={14} className="mt-0.5 shrink-0 text-[#d88b32]" />{item}</div>)}</div></Surface><Surface className="p-5"><SectionHeader title="Frontend foundations" /><div className="grid grid-cols-2 gap-2">{[['Service seams','Ready'],['Local cache','Ready'],['Responsive shell','Ready'],['Demo mode','Active']].map(([a,b]) => <div key={a} className="rounded-xl bg-[#f2f8f7] p-3"><MiniLabel>{a}</MiniLabel><div className="mt-1 text-[11px] font-bold text-[#4c7776]">{b}</div></div>)}</div></Surface></div></div></div>; }

function NotFoundPage() { return <div className="flex min-h-[70vh] flex-col items-center justify-center text-center"><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e3f3f0] text-[#20777b]"><Compass size={26} /></div><h1 className="mt-5 text-2xl font-bold text-[#285b61]">Chart not found</h1><p className="mt-2 text-sm text-[#78908f]">This coordinate does not exist in the current demo.</p><Link href="/dashboard" className="mt-5 rounded-xl bg-[#126972] px-4 py-2.5 text-xs font-bold text-white" data-testid="link-return-dashboard">Return to overview</Link></div>; }

function Router() {
  return <Shell><ErrorBoundary><Switch><Route path="/" component={Dashboard} /><Route path="/dashboard" component={Dashboard} /><Route path="/map" component={MapPage} /><Route path="/pfz" component={PfzPage} /><Route path="/weather" component={WeatherPage} /><Route path="/risk" component={RiskPage} /><Route path="/route" component={RoutePage} /><Route path="/alerts" component={AlertsPage} /><Route path="/assistant" component={AssistantPage} /><Route path="/offline" component={OfflinePage} /><Route path="/about" component={AboutPage} /><Route component={NotFoundPage} /></Switch></ErrorBoundary></Shell>;
}

export default function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider>;
}